const YV_LIST=[['inv','Inventory'],['min','Minimum vs available'],['rcv','Receive'],['iss','Issue'],['req','Requisition status']];
const KV_LIST=[['exec','Production & execution'],['plan','Knitting planning'],['day','Day plan & production']];
function render(){KCACHE=null;const ae=document.activeElement;const keep=ae&&ae.tagName==='INPUT'&&ae.type==='search'&&ae.id&&root.contains(ae)?ae:null;const m=G('ykmain');
 if(TOP==='yarn')({inv:yInv,min:yMin,rcv:yRcv,iss:yIss,req:yReq})[YV](m);else({exec:kExec,plan:kPlan,day:kDay})[KV](m);
 if(keep){const nw=root.querySelector('#'+keep.id);if(nw&&nw!==keep){const hi=nw.oninput;keep.oninput=e=>{nw.value=keep.value;if(hi)hi.call(nw,e)};nw.replaceWith(keep);try{keep.focus({preventScroll:true})}catch(e){}}}}
