render();
return{main:[['yarn','Yarn Store'],['knit','Knitting']],get top(){return TOP},get views(){return TOP==='yarn'?YV_LIST:KV_LIST},get view(){return TOP==='yarn'?YV:KV},
 setTop(t){TOP=t;resetF();SEL=null;OPENP=null;render()},setView(v){if(TOP==='yarn')YV=v;else KV=v;resetF();SEL=null;render()},reset(){S=JSON.parse(JSON.stringify(DEF));S.pend=seedPending().map(p=>Object.assign(p,{status:'Pending'}));save();render()},rerender:render,roleSel:rs};
